		if($stage && $stage.dialog && $stage.dialog.commFriendQuery && $stage.dialog.commFriendQuery.length){
			$stage.dialog.commFriendQuery.val("");
		}
		$data._friendSearchLoading = false;
		$data._friendSearchResults = null;
		renderFriendsPage();
