	var picked = DEFINITION_CARD_ACCENTS[index % DEFINITION_CARD_ACCENTS.length] || DEFINITION_CARD_ACCENTS[0];
	if($data) $data._definitionAccentIndex = (index + 1) % DEFINITION_CARD_ACCENTS.length;
	return picked;
